package com.example.clientdemopublicqa.api;

import io.restassured.RestAssured;
import io.restassured.specification.RequestSpecification;

/**
 * Shared utility for building RestAssured request specifications.
 *
 * <p>Use {@link #baseSpec(String)} to obtain a pre-configured
 * {@link RequestSpecification} targeting the given base URL.
 *
 * Generated by qaff (Quality Impact Pack).
 */
public final class ApiTestSupport {

    private ApiTestSupport() {
        // utility class — no instances
    }

    /**
     * Returns a RestAssured {@link RequestSpecification} targeting the
     * given base URL.
     *
     * @param baseUrl the target base URL, e.g. {@code "http://127.0.0.1:8080"}
     * @return a configured {@link RequestSpecification}
     */
    public static RequestSpecification baseSpec(String baseUrl) {
        return RestAssured.given().baseUri(baseUrl);
    }
}
